 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Uniform full-length lines mark the frame separators.
    sep_values = []
    for row in g:
        if len(set(row)) == 1:
            sep_values.append(row[0])
    for c in range(w):
        col = [g[r][c] for r in range(h)]
        if len(set(col)) == 1:
            sep_values.append(col[0])
    # Separator color is the value occurring on most full uniform lines.
    counts = {v: sep_values.count(v) for v in set(sep_values)}
    sep = max(counts, key=counts.get)
    row_cuts = [r for r in range(h) if all(x == sep for x in g[r])]
    col_cuts = [c for c in range(w) if all(g[r][c] == sep for r in range(h))]
    def intervals(n, cuts):
        out, start = [], 0
        for k in cuts:
            if start < k: out.append((start, k))
            start = k + 1
        if start < n: out.append((start, n))
        return out
    rows, cols = intervals(h, row_cuts), intervals(w, col_cuts)
    bg_counts = {}
    for r in range(h):
        for c in range(w):
            if g[r][c] != sep: bg_counts[g[r][c]] = bg_counts.get(g[r][c], 0) + 1
    bg = max(bg_counts, key=bg_counts.get)
    template = None
    for r0, r1 in rows:
        for c0, c1 in cols:
            if any(g[r][c] != bg for r in range(r0, r1) for c in range(c0, c1)):
                template = [row[c0:c1] for row in g[r0:r1]]
                break
        if template is not None: break
    if template is None: return g
    for r0, r1 in rows:
        for c0, c1 in cols:
            if (r1-r0, c1-c0) != (len(template), len(template[0])): continue
            for dr in range(r1-r0):
                for dc in range(c1-c0):
                    g[r0+dr][c0+dc] = template[dr][dc]
    return g

